using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Web.Script.Serialization;

static class UpdateInstaller {
 static readonly JavaScriptSerializer json=new JavaScriptSerializer();
 static string Value(Dictionary<string,object> plan,string key){object value;return plan.TryGetValue(key,out value)?Convert.ToString(value,System.Globalization.CultureInfo.InvariantCulture):"";}
 public static bool NeedsElevation(string directory){string probe=Path.Combine(directory,".Feng-write-"+Guid.NewGuid().ToString("N"));try{using(new FileStream(probe,FileMode.CreateNew,FileAccess.Write,FileShare.None,1,FileOptions.DeleteOnClose)){}return false;}catch(UnauthorizedAccessException){return true;}catch(System.Security.SecurityException){return true;}}
 public static void Start(string downloaded,ReleaseInfo release){if(release==null||!release.CanInstall)throw new InvalidOperationException("没有高于当前版本的可安装更新。");if(!UpdateService.CanRestart)throw new InvalidOperationException("请先结束当前闯关或评测，再更新软件。");UpdateService.Verify(downloaded,release.Sha256,release.Size,release.Version);var app=System.Windows.Application.Current;if(app==null)throw new InvalidOperationException("请在软件设置中执行更新。");foreach(var w in app.Windows.OfType<MainWindow>())w.SaveForUpdate();foreach(var w in app.Windows.OfType<ChallengeWindow>())w.SaveForUpdate();string target=Assembly.GetExecutingAssembly().Location,dir=Path.GetDirectoryName(Path.GetFullPath(downloaded)),helper=Path.Combine(dir,"updater-runner.exe"),manifest=Path.Combine(dir,"apply.json");string pending=Path.Combine(Path.GetDirectoryName(target),".Feng-update-"+Guid.NewGuid().ToString("N")+".exe");bool elevate=NeedsElevation(Path.GetDirectoryName(target));File.Copy(target,helper,false);var parent=Process.GetCurrentProcess();var plan=new Dictionary<string,object>{{"target",target},{"pending",pending},{"source",Path.GetFullPath(downloaded)},{"sha",release.Sha256},{"size",release.Size},{"version",release.Version.ToString()},{"oldSha",UpdateService.HashFile(target)},{"elevate",elevate},{"pid",parent.Id},{"started",parent.StartTime.ToUniversalTime().Ticks}};File.WriteAllText(manifest,json.Serialize(plan),new UTF8Encoding(false));var runner=Process.Start(new ProcessStartInfo(helper,"--apply-update \""+manifest+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,WorkingDirectory=dir});if(runner==null)throw new IOException("无法启动更新助手，原程序仍可继续使用。");app.Shutdown();}
 static Dictionary<string,object> Plan(string manifest){string here=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);if(Path.GetFileName(Assembly.GetExecutingAssembly().Location)!="updater-runner.exe"||Path.GetFullPath(manifest)!=Path.Combine(here,"apply.json"))throw new InvalidDataException("更新计划位置无效。");var plan=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(manifest));string target=Path.GetFullPath(Value(plan,"target")),pending=Path.GetFullPath(Value(plan,"pending")),source=Path.GetFullPath(Value(plan,"source"));if(Path.GetDirectoryName(source)!=here||Path.GetDirectoryName(pending)!=Path.GetDirectoryName(target)||!Path.GetFileName(pending).StartsWith(".Feng-update-",StringComparison.Ordinal)||!target.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)||target==pending||target==source||target==Assembly.GetExecutingAssembly().Location)throw new InvalidDataException("更新目标或来源无效。");Version version;if(!UpdateService.TryVersion(Value(plan,"version"),out version)||version<=UpdateService.Current)throw new InvalidDataException("禁止降级更新。");UpdateService.Verify(source,Value(plan,"sha"),long.Parse(Value(plan,"size")),version);return plan;}
 static void WaitParent(Dictionary<string,object> plan){try{using(var parent=Process.GetProcessById(int.Parse(Value(plan,"pid")))){if(parent.StartTime.ToUniversalTime().Ticks!=long.Parse(Value(plan,"started"))||!string.Equals(parent.MainModule.FileName,Value(plan,"target"),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("原程序身份不匹配。");if(!parent.WaitForExit(60000))throw new IOException("原程序仍在运行，更新已取消。");}}catch(ArgumentException){}}
 static void Swap(Dictionary<string,object> plan){string source=Value(plan,"source"),pending=Value(plan,"pending"),target=Value(plan,"target");Version version;UpdateService.TryVersion(Value(plan,"version"),out version);if(!string.Equals(UpdateService.HashFile(target),Value(plan,"oldSha"),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("等待期间原EXE发生变化，未替换文件。");File.Copy(source,pending,false);UpdateService.Verify(pending,Value(plan,"sha"),long.Parse(Value(plan,"size")),version);File.Replace(pending,target,target+".previous",true);}
 static void Launch(string target){var p=Process.Start(new ProcessStartInfo(target){UseShellExecute=true,WorkingDirectory=Path.GetDirectoryName(target)});if(p==null)throw new IOException("无法启动更新后的程序。");}
 public static int Apply(string manifest,bool elevated,bool silent=false){Dictionary<string,object> plan=null;bool replaced=false;string result=Path.Combine(Path.GetDirectoryName(manifest),"update-result.txt");try{plan=Plan(manifest);if(elevated&&Value(plan,"elevate")!="True")throw new InvalidDataException("本次更新无需提升权限。");WaitParent(plan);if(!elevated&&Value(plan,"elevate")=="True"){
    // A normal coordinator launches the privileged file worker, then restarts the app with its original user token.
    var worker=Process.Start(new ProcessStartInfo(Assembly.GetExecutingAssembly().Location,"--apply-elevated \""+manifest+"\""){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden,WorkingDirectory=Path.GetDirectoryName(manifest)});if(worker==null||!worker.WaitForExit(120000)||worker.ExitCode!=0)throw new IOException("系统授权或更新写入未完成，原程序会保留。");Version version;UpdateService.TryVersion(Value(plan,"version"),out version);UpdateService.Verify(Value(plan,"target"),Value(plan,"sha"),long.Parse(Value(plan,"size")),version);replaced=true;
   }else{Swap(plan);replaced=true;}if(elevated){File.WriteAllText(result,"APPLIED "+Value(plan,"version"));return 0;}Launch(Value(plan,"target"));File.WriteAllText(result,"SUCCESS "+Value(plan,"version"));return 0;
  }catch(Exception ex){if(plan!=null){string target=Value(plan,"target"),pending=Value(plan,"pending"),backup=target+".previous";if(replaced&&File.Exists(backup))try{File.Replace(backup,target,null,true);}catch{}try{if(File.Exists(pending))File.Delete(pending);}catch{}if(!elevated)try{Launch(target);}catch{}}try{File.WriteAllText(result,"FAILED "+ex);}catch{}if(!elevated&&!silent)System.Windows.MessageBox.Show("更新未完成，原程序已保留。\n"+ex.Message,"Feng · 更新助手");return 1;}}
}
